create table public.jackpot_candidates(id uuid primary key default gen_random_uuid(),candidate_key text not null unique,asset_id uuid not null references public.assets(id),strategy text not null,active_window_start timestamptz not null,detected_at timestamptz not null,current_state text not null check(current_state in('DISCOVERED','WATCHING','ACCELERATING','JACKPOT_CANDIDATE','QUALIFIED','REJECTED','EXPIRED','INSUFFICIENT_DATA')),current_revision integer not null default 0,collector_version text not null,created_from_event_id text not null references public.event_outbox(event_id),expires_at timestamptz not null,created_at timestamptz not null default now());
create table public.jackpot_candidate_revisions(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.jackpot_candidates(id),revision_number integer not null,revision_type text not null check(revision_type in('v0_detection','v1_acceleration','v2_wallet_enrichment','v3_risk_liquidity','v4_outcome')),state text not null,trigger_event_id text references public.event_outbox(event_id),information_cutoff_at timestamptz not null,available_at timestamptz not null,features jsonb not null,probability_features jsonb not null default'{}',payoff_features jsonb not null default'{}',safety_result jsonb not null default'{}',evidence_refs jsonb not null default'[]',revision_hash text not null,created_at timestamptz not null default now(),unique(candidate_id,revision_number),unique(candidate_id,revision_hash));
create table public.jackpot_candidate_outcomes(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references public.jackpot_candidates(id),evaluated_at timestamptz not null,information_cutoff_at timestamptz not null,prices jsonb not null,max_price numeric,max_multiple numeric,time_to jsonb not null,mfe numeric,mae numeric,data_quality smallint not null,provider text not null,unique(candidate_id,information_cutoff_at,provider));
create or replace function public.prevent_jackpot_mutation()returns trigger language plpgsql as $$begin raise exception'Jackpot history is immutable';end$$;create trigger jackpot_revisions_immutable before update or delete on public.jackpot_candidate_revisions for each row execute function public.prevent_jackpot_mutation();create trigger jackpot_outcomes_immutable before update or delete on public.jackpot_candidate_outcomes for each row execute function public.prevent_jackpot_mutation();
alter table public.jackpot_candidates enable row level security;alter table public.jackpot_candidate_revisions enable row level security;alter table public.jackpot_candidate_outcomes enable row level security;create policy "public read jackpot candidates" on public.jackpot_candidates for select using(true);create policy "public read jackpot revisions" on public.jackpot_candidate_revisions for select using(true);create policy "public read jackpot outcomes" on public.jackpot_candidate_outcomes for select using(true);grant select on public.jackpot_candidates,public.jackpot_candidate_revisions,public.jackpot_candidate_outcomes to anon,authenticated;grant all privileges on public.jackpot_candidates,public.jackpot_candidate_revisions,public.jackpot_candidate_outcomes to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes'));
